pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 v1, uint256 v2, address logAddr) internal {
        try c.SetMinSum(v1) {} catch { return; }
        try c.Initialized() {} catch { return; }
        bool revertedMinSum;
        try c.SetMinSum(v2) { revertedMinSum = false; } catch { revertedMinSum = true; }
        bool revertedLogFile;
        try c.SetLogFile(logAddr) { revertedLogFile = false; } catch { revertedLogFile = true; }
        assertTrue(revertedMinSum && revertedLogFile && c.MinSum() == v1);
    }

    function testFuzz_run(uint256 v1, uint256 v2, address logAddr) public {
        vm.assume(logAddr.code.length == 0 && uint160(logAddr) > 0xffff && logAddr != address(this) && logAddr != address(c) && logAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && logAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(v1, v2, logAddr);
    }

    receive() external payable {}
}
